import sys, numpy as np, mujoco
sys.path.insert(0,'/opt/tools'); import casa_tool
s=casa_tool.Session()
m,d=s.model,s.data
for i in range(m.nbody):
 n=m.body(i).name
 if n: print(i,n,d.xpos[i].round(3), 'parent',m.body(i).parentid)
print('--- joints likely')
for i in range(m.njnt):
 n=m.joint(i).name
 if any(x in n.lower() for x in ['obj','container']): print(i,n,'qpos',d.qpos[m.joint(i).qposadr[0]:m.joint(i).qposadr[0]+(7 if m.joint(i).type==mujoco.mjtJoint.mjJNT_FREE else 1)])
print('--- geom names')
for i in range(m.ngeom):
 n=m.geom(i).name
 if any(x in n.lower() for x in ['obj','container']): print(i,n,'body',m.body(m.geom_bodyid[i]).name,'size',m.geom_size[i], 'pos',d.geom_xpos[i].round(3))
print('eef id',s.env.robots[0].eef_site_id)
for name,id in s.env.robots[0].eef_site_id.items(): print(name,d.site_xpos[id],d.site_xmat[id].reshape(3,3))
from PIL import Image
for cam in s.camera_views:
 Image.fromarray(s.render(cam)).save('/app/output/'+cam+'.png')
PY

